import{_ as n,c as t,o as i,ah as a}from"./chunks/framework.CDiWxQbG.js";const r="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard.jpg",s="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard_tabs.jpg",l="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard_overview.jpg",h="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard_trench.jpg",d="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard_trench_hover.jpg",o="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard_conduit.jpg",c="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard_node.jpg",u="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard_address.jpg",g="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard_area.jpg",m="/Qonnectra-docs/pr-18/images/manual/teil-a/dashboard_warranty.jpg",R=JSON.parse('{"title":"4. Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/04-dashboard.md","filePath":"manual/teil-a-anwenderhandbuch/04-dashboard.md"}'),b={name:"manual/teil-a-anwenderhandbuch/04-dashboard.md"};function p(f,e,k,z,_,w){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="_4-dashboard" tabindex="-1">4. Dashboard <a class="header-anchor" href="#_4-dashboard" aria-label="Permalink to &quot;4. Dashboard&quot;">​</a></h1><p>Das <strong>Dashboard</strong> ist die zentrale Übersichtsseite von Qonnectra. Es fasst den dokumentierten Netzbestand eines Projekts in Kennzahlen und Diagrammen zusammen, damit Sie den Ausbauzustand ohne Umweg über Listen oder die Karte erfassen können. Nach der Anmeldung ist das Dashboard die Startansicht; später erreichen Sie es über die linke Navigationsleiste in der Gruppe „Info“ durch Klicken auf den Menüpunkt „Dashboard“.</p><p><img src="'+r+'" alt="Screenshot Dashboard" data-zoomable="true"></p><p>Alle Auswertungen beziehen sich auf das Projekt, das oben links in der Kopfzeile ausgewählt ist (siehe Abschnitt <a href="./01-erste-schritte.html#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>), und sind ausschließlich zur Ansicht bestimmt: Werte lassen sich hier nicht bearbeiten, eine Exportfunktion gibt es nicht.</p><p>Unterhalb der Kopfzeile stehen sechs Reiter (Tabs): „Übersicht“ mit den Kennzahlen aller Datenbereiche auf einen Blick sowie „Trasse“, „Rohre“, „Netzknoten“, „Adressen“ und „Gebiete“ mit den Auswertungen des jeweiligen Bereichs. Alle Auswertungen werden beim Öffnen des Dashboards gemeinsam geladen, der Wechsel zwischen den Reitern lädt also keine Daten nach.</p><p><img src="'+s+'" alt="Screenshot Dashboard mit Hervorhebung der Reiterleiste oberhalb der Inhaltsfläche" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Bei einem schmalen Fenster sind nicht alle sechs Beschriftungen gleichzeitig zu sehen. Die Reiterleiste lässt sich dann waagerecht verschieben, zeigt dabei aber keinen Scrollbalken.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Liegen für ein Diagramm keine Werte vor, steht an seiner Stelle „Keine Daten verfügbar“. Das ist kein Fehler: Fehlt eine Angabe im Projekt durchgängig – etwa die Netzebene der Rohre –, bleibt das zugehörige Diagramm leer, während die übrigen gefüllt sind.</p></div><h2 id="_4-1-reiter-„ubersicht" tabindex="-1">4.1 Reiter „Übersicht“ <a class="header-anchor" href="#_4-1-reiter-„ubersicht" aria-label="Permalink to &quot;4.1 Reiter „Übersicht“&quot;">​</a></h2><p>Der Reiter „Übersicht“ enthält sechs Karten. Jede nennt eine oder zwei Kennzahlen und darunter die Aufschlüsselung als Liste; der farbige Balken im Hintergrund einer Zeile zeigt deren Anteil am größten Wert der Liste.</p><ul><li>„Trassenstatistik“ – Gesamtlänge aller Trassen, aufgeschlüsselt nach Verlegeart und Oberfläche</li><li>„Netzknotenstatistik“ – Anzahl aller Netzknoten, aufgeschlüsselt nach Knotentyp</li><li>„Rohrstatistiken“ – Gesamtlänge aller Rohre, aufgeschlüsselt nach Rohrtyp</li><li>„Adress-Statistiken“ – Adressen und Wohneinheiten gesamt, aufgeschlüsselt nach Ort</li><li>„Gebietsstatistiken“ – Anzahl und Gesamtfläche der Gebiete, aufgeschlüsselt nach Gebietstyp</li><li>„Gewährleistung“ – die als nächstes ablaufenden Gewährleistungsfristen, siehe Abschnitt <a href="#_4-7-gewahrleistungsfristen-im-blick-behalten">Gewährleistungsfristen im Blick behalten</a></li></ul><p><img src="'+l+'" alt="Screenshot Dashboard mit Hervorhebung der Karten im Reiter „Übersicht“ in der Inhaltsfläche" data-zoomable="true"></p><p>Adressen ohne Ortsangabe und Gebiete ohne Typ erscheinen in ihrer Liste unter „Unbekannt“.</p><h2 id="_4-2-reiter-„trasse" tabindex="-1">4.2 Reiter „Trasse“ <a class="header-anchor" href="#_4-2-reiter-„trasse" aria-label="Permalink to &quot;4.2 Reiter „Trasse“&quot;">​</a></h2><p>Im Reiter „Trasse“ finden Sie acht Diagramme zu den Trassen des Projekts:</p><ul><li>„Gesamtlänge pro Oberfläche“</li><li>„Gesamtlänge pro Verlegeart“</li><li>„Durchschnittliche Hausanschlusslänge“</li><li>„Länge gefördert“ – über die als gefördert gekennzeichneten Trassen</li><li>„Länge Eigenleistung“ – über die in Eigenleistung erbrachten Trassen</li><li>„Gesamtlänge pro Status“</li><li>„Gesamtlänge pro Netzebene“</li><li>„Längsten Trassen im Netz“ – die fünf längsten Trassen, beschriftet mit Verlegeart und Oberfläche</li></ul><p class="img-row"><img src="'+h+'" alt="Screenshot Dashboard mit Hervorhebung der Diagramme im Reiter „Trasse“ in der Inhaltsfläche" data-zoomable="true"><img src="'+d+'" alt="Screenshot Ausschnittvergrößerung des Diagramms „Gesamtlänge pro Oberfläche“ mit dem Tooltip über einem Balken" data-zoomable="true"></p><p>Genaue Werte lesen Sie einzeln ab: Zeigen Sie mit der Maus auf einen Balken, erscheint ein Tooltip mit dem Wert und seiner Einheit. Das gilt ebenso für die Segmente der Ringdiagramme in den übrigen Reitern; dort nennt der Tooltip zusätzlich den Anteil in Prozent.</p><h2 id="_4-3-reiter-„rohre" tabindex="-1">4.3 Reiter „Rohre“ <a class="header-anchor" href="#_4-3-reiter-„rohre" aria-label="Permalink to &quot;4.3 Reiter „Rohre“&quot;">​</a></h2><p>Der Reiter „Rohre“ beginnt mit dem Kasten „Top 5 längste Rohre“, der Rang, Name, Typ und Länge der fünf längsten Rohre nennt; sind keine Rohre vorhanden, fehlt der Kasten. Darunter folgen die Diagramme:</p><ul><li>„Länge nach Rohrtyp“</li><li>„Länge nach Status und Typ“ – gestapelte Balken je Status, aufgeschlüsselt nach Rohrtyp</li><li>„Gesamtlänge pro Netzebene“ – Ringdiagramm</li><li>„Durchschnittliche Länge nach Typ“</li><li>„Anzahl Rohre nach Status“</li><li>„Länge nach Eigentümer“</li><li>„Länge nach Hersteller“ – Ringdiagramm</li><li>„Rohre im Zeitverlauf“ – Anzahl der Rohre je Monat</li></ul><p><img src="'+o+'" alt="Screenshot Dashboard mit Hervorhebung der Auswertungen im Reiter „Rohre“ in der Inhaltsfläche" data-zoomable="true"></p><p>Angelegt und bearbeitet werden Rohre im Bereich Rohrverwaltung, siehe Kapitel <a href="./10-rohrverwaltung.html">Rohrverwaltung</a>.</p><h2 id="_4-4-reiter-„netzknoten" tabindex="-1">4.4 Reiter „Netzknoten“ <a class="header-anchor" href="#_4-4-reiter-„netzknoten" aria-label="Permalink to &quot;4.4 Reiter „Netzknoten“&quot;">​</a></h2><p>Der Reiter „Netzknoten“ enthält sechs Diagramme: „Netzknoten nach Ort“, „Netzknoten nach Status“, „Netzknoten nach Netzebene“, „Netzknoten nach Typ“, „Netzknoten nach Eigentümer“ und „Neueste Netzknoten“.</p><p><img src="'+c+'" alt="Screenshot Dashboard mit Hervorhebung der Diagramme im Reiter „Netzknoten“ in der Inhaltsfläche" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>„Neueste Netzknoten“ ist eine Aufzählung, keine Mengenauswertung. Das Diagramm listet die fünf zuletzt datierten Netzknoten mit Namen und Typ auf; alle Balken sind deshalb gleich lang. Netzknoten, bei denen die jeweilige Angabe fehlt, bleiben in allen Diagrammen unberücksichtigt – die Summe der Balken muss daher nicht der Gesamtzahl aus dem Reiter „Übersicht“ entsprechen.</p></div><h2 id="_4-5-reiter-„adressen" tabindex="-1">4.5 Reiter „Adressen“ <a class="header-anchor" href="#_4-5-reiter-„adressen" aria-label="Permalink to &quot;4.5 Reiter „Adressen“&quot;">​</a></h2><p>Der Reiter „Adressen“ enthält vier Diagramme: „Adressen nach Ort“, „Adressen nach Ausbaustatus“, „Wohneinheiten nach Ort“ und „Wohneinheiten nach Typ“ als Ringdiagramm.</p><p><img src="'+u+'" alt="Screenshot Dashboard mit Hervorhebung der Diagramme im Reiter „Adressen“ in der Inhaltsfläche" data-zoomable="true"></p><h2 id="_4-6-reiter-„gebiete" tabindex="-1">4.6 Reiter „Gebiete“ <a class="header-anchor" href="#_4-6-reiter-„gebiete" aria-label="Permalink to &quot;4.6 Reiter „Gebiete“&quot;">​</a></h2><p>Der Reiter „Gebiete“ zeigt, wie viele Gebiete im Projekt hinterlegt sind und welcher Anteil des Bestands innerhalb dieser Gebiete liegt. In der ersten Reihe stehen die Karten „Anzahl Gebiete“, „Gesamtfläche“ und „Gebiete nach Typ“ als Ringdiagramm.</p><p>Darunter folgen drei Karten zur <strong>Abdeckung</strong> – „Adress-Abdeckung“, „Netzknoten-Abdeckung“ und „Wohneinheiten-Abdeckung“. Jede nennt den Wert innerhalb der Gebiete, den Gesamtwert des Projekts und den auf ganze Zahlen gerundeten Anteil in Prozent.</p><p>Den unteren Block bilden sechs Diagramme: „Adressen pro Gebiet“, „Adressen nach Gebietstyp“, „Netzknoten pro Gebiet“, „Netzknoten nach Gebietstyp“, „Trassenlänge pro Gebiet“ und „Wohneinheiten nach Gebietstyp“.</p><p><img src="'+g+'" alt="Screenshot Dashboard mit Hervorhebung der Karten und Diagramme im Reiter „Gebiete“ in der Inhaltsfläche" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Diagramme „Adressen pro Gebiet“, „Netzknoten pro Gebiet“ und „Trassenlänge pro Gebiet“ zeigen höchstens die zehn Gebiete mit den höchsten Werten. Bei mehr als zehn Gebieten ist die Auswertung also keine vollständige Liste. Gebiete, in denen es keine Adressen, keine Netzknoten bzw. keine Trassen gibt, fehlen darin ganz.</p></div><h2 id="_4-7-gewahrleistungsfristen-im-blick-behalten" tabindex="-1">4.7 Gewährleistungsfristen im Blick behalten <a class="header-anchor" href="#_4-7-gewahrleistungsfristen-im-blick-behalten" aria-label="Permalink to &quot;4.7 Gewährleistungsfristen im Blick behalten&quot;">​</a></h2><p>Die Karte „Gewährleistung“ im Reiter „Übersicht“ zeigt bis zu fünf Netzknoten, deren Gewährleistungsfrist als nächste abläuft, aufsteigend nach Datum sortiert. Je Eintrag stehen der Name des Netzknotens, die verbleibende Restlaufzeit und das Ablaufdatum. Die Einträge sind nach Dringlichkeit farbig hinterlegt:</p><ul><li>rot: weniger als 30 Tage Restlaufzeit</li><li>gelb: weniger als 90 Tage Restlaufzeit</li><li>grün: 90 Tage Restlaufzeit oder mehr</li></ul><p>Sind für das Projekt keine Fristen hinterlegt, erscheint stattdessen „Keine Garantien laufen bald ab“.</p><p><img src="'+m+'" alt="Screenshot Dashboard mit Hervorhebung der Karte „Gewährleistung“ und ihren farbig hinterlegten Einträgen unten rechts in der Inhaltsfläche" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Karte ist keine vollständige Liste aller Gewährleistungsfristen des Projekts – sie zeigt höchstens fünf Netzknoten, bereits abgelaufene Fristen erscheinen nicht mehr. Die Frist eines einzelnen Netzknotens finden Sie in dessen Info-Box im Reiter „Eigenschaften“ (siehe Kapitel <a href="./05-karte.html">Karte</a>).</p></div><h2 id="_4-8-nach-kennzeichen-filtern-und-wie-aktuell-die-werte-sind" tabindex="-1">4.8 Nach Kennzeichen filtern und wie aktuell die Werte sind <a class="header-anchor" href="#_4-8-nach-kennzeichen-filtern-und-wie-aktuell-die-werte-sind" aria-label="Permalink to &quot;4.8 Nach Kennzeichen filtern und wie aktuell die Werte sind&quot;">​</a></h2><h3 id="_4-8-1-nach-kennzeichen-filtern" tabindex="-1">4.8.1 Nach Kennzeichen filtern <a class="header-anchor" href="#_4-8-1-nach-kennzeichen-filtern" aria-label="Permalink to &quot;4.8.1 Nach Kennzeichen filtern&quot;">​</a></h3><p>Einen Filter nach Kennzeichen gibt es im Dashboard nicht: Seine Kennzahlen, Diagramme und Karten beziehen sich immer auf den gesamten Bestand des ausgewählten Projekts.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Brauchen Sie die Auswertung eines einzelnen Kennzeichens, grenzen Sie in der jeweiligen Ansicht ein. Welche das anbieten, nennt Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-6-kennzeichen-als-projektweiter-filter">Kennzeichen als projektweiter Filter</a>.</p></div><h3 id="_4-8-2-wie-aktuell-die-werte-sind" tabindex="-1">4.8.2 Wie aktuell die Werte sind <a class="header-anchor" href="#_4-8-2-wie-aktuell-die-werte-sind" aria-label="Permalink to &quot;4.8.2 Wie aktuell die Werte sind&quot;">​</a></h3><p>Das Dashboard liest seine Werte nicht bei jedem Aufruf neu aus der Datenbank.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Kennzahlen werden auf dem Server bis zu fünf Minuten zwischengespeichert. Daten, die Sie gerade in einer anderen Ansicht erfasst haben, erscheinen deshalb unter Umständen erst mit einigen Minuten Verzögerung – ein Neuladen der Seite beschleunigt das nicht.</p></div>',49)])])}const A=n(b,[["render",p]]);export{R as __pageData,A as default};
